import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
const root='/Users/shopme/Documents/workspace/opendesk-browser';
const checkerPath=resolve(root,'tests/framework/verify-product-acceptance.mjs');
const testPath=resolve(root,'tests/framework/acceptance-evidence.test.mjs');
const {validateAcceptance,reviewInputSnapshot,CRASH_POINTS,SUPPLEMENTAL_CATALOG}=await import(pathToFileURL(checkerPath));
const hash=x=>createHash('sha256').update(x).digest('hex');
const checker=await readFile(checkerPath,'utf8'), tests=await readFile(testPath,'utf8');
const fixture=new Function('createHash','CRASH_POINTS','reviewInputSnapshot',
 tests.slice(tests.indexOf("const hash = "),tests.indexOf('\nfunction rejects('))+'\nreturn fixture;')(createHash,CRASH_POINTS,reviewInputSnapshot);
const output=[];
function record(name,finding,expected,actual){output.push({name,finding,expected,...actual});}
function resign(d){const s=reviewInputSnapshot(d);for(const r of d.candidate.reviews||[])if(r&&typeof r==='object'){r.reviewedInputs=s;r.reviewInputsSha256=hash(JSON.stringify(s));}}
function run(name,finding,change,code,{fresh=true}={}) {
 const d=fixture();change(d);if(fresh)resign(d);
 try {const r=validateAcceptance(d),codes=[...new Set(r.issues.map(x=>x.code))];
 record(name,finding,code,{passed:r.accepted===false&&r.counts.accepted===0&&codes.includes(code),accepted:r.accepted,codes});}
 catch(e){record(name,finding,code,{passed:false,error:String(e)});}
}
const baseline=validateAcceptance(fixture());
record('synthetic baseline and reviewedInputs export','BASELINE','accepted=true; snapshot returned',{passed:baseline.accepted&&baseline.counts.accepted===3&&JSON.stringify(baseline.reviewedInputs)===JSON.stringify(reviewInputSnapshot(fixture())),accepted:baseline.accepted});
function duplicate(d,name,change) {
 const original=d.records.find(r=>r.id===d.candidate.campaigns[name][0]), r=structuredClone(original);
 r.id+='-extra';
 for(const o of r.observations){o.occurrence.resultId=r.id;o.occurrence.roundId=r.id+'-'+o.environmentId;o.occurrence.pointer='/'+r.id+'/'+o.environmentId;}
 change(r);d.records.push(r);d.candidate.campaigns[name].push(r.id);
}
run('good concurrency cannot mask second bad record','AMR-01',d=>duplicate(d,'sdkConcurrency',r=>r.observations[1].measurements.httpWrites=2),'SDK_100_NOT_PROVEN');
run('good crash cannot mask same-kind replay','AMR-01',d=>{
 const r=structuredClone(d.records.find(r=>r.kind==='write-before-receipt'));r.id+='-extra';
 for(const o of r.observations){o.occurrence.resultId=r.id;o.occurrence.roundId=r.id+'-'+o.environmentId;o.occurrence.pointer='/'+r.id+'/'+o.environmentId;}
 r.observations[1].measurements.replayed=true;d.records.push(r);d.candidate.campaigns.sdkCrashes.push(r.id);
},'SDK_CRASH_NOT_PROVEN');
run('good download cannot mask accepted-only second record','AMR-01',d=>duplicate(d,'downloads',r=>r.observations[1].download.state='accepted'),'DISK_DOWNLOAD_NOT_PROVEN');
run('good termination cannot mask >3s','AMR-01',d=>duplicate(d,'workerTermination',r=>r.observations[1].measurements.terminatedMs=3001),'WORKER_TERMINATION_NOT_PROVEN');
run('good termination cannot mask borrowed page closure','AMR-01',d=>duplicate(d,'workerTermination',r=>r.observations[1].measurements.borrowedPageClosed=true),'WORKER_TERMINATION_NOT_PROVEN');
run('different result ID cannot reuse session/round','AMR-02',d=>{
 const [a,b]=d.records.filter(r=>r.id==='mixed-0'||r.id==='mixed-1');b.observations[0].occurrence.roundId=a.observations[0].occurrence.roundId;
},'CAMPAIGN_OCCURRENCE_REUSED');
run('different round cannot reuse raw hash/pointer','AMR-02',d=>{
 const [a,b]=d.records.filter(r=>r.id==='mixed-0'||r.id==='mixed-1');b.observations[0].occurrence.pointer=a.observations[0].occurrence.pointer;
},'CAMPAIGN_OCCURRENCE_REUSED');
run('missing occurrence rejects','AMR-02',d=>delete d.records.find(r=>r.id==='mixed-0').observations[0].occurrence,'CAMPAIGN_OCCURRENCE_MISSING');
run('additional contract hash cannot be omitted','AMR-03',d=>delete d.records[2].contractSha256,'CASE_CONTRACT_MISMATCH');
run('additional contract mismatch rejects','AMR-03',d=>d.records[2].contractSha256='b'.repeat(64),'CASE_CONTRACT_MISMATCH');
run('additional frozen source path requires exact source hash key','AMR-03',d=>{
 d.supplementalSpec.cases[0].source.path='contract-source';d.records[2].contractSha256=hash(JSON.stringify(d.supplementalSpec.cases[0]));
},'SOURCE_BINDING_MISSING');
run('missing environment ID rejects','AMR-10',d=>delete d.candidate.environments[0].id,'ENVIRONMENT_INCOMPLETE');
run('array Chrome version rejects','AMR-10',d=>d.candidate.environments[0].chromeVersion=['138.0.0.1'],'ENVIRONMENT_INCOMPLETE');
const snapshotChanges=[
 ['spec',d=>d.spec.cases[0].expected='different'],
 ['catalog',d=>d.supplementalSpec.cases[0].expected='different'],
 ['source',d=>d.records[0].sourceHashes.other='b'.repeat(64)],
 ['build',d=>d.candidate.buildReport={path:'changed-build.json',sha256:'b'.repeat(64)}],
 ['pack',d=>d.candidate.packReport={path:'changed-pack.json',sha256:'b'.repeat(64)}],
 ['archive',d=>d.candidate.packageArchive={path:'changed.zip',sha256:'b'.repeat(64)}],
 ['environment',d=>d.candidate.environments[0].profile='different'],
 ['result report',d=>d.candidate.resultReports=[{path:'changed.json',sha256:'b'.repeat(64)}]],
 ['record data',d=>d.records[0].observations[0].actual='different'],
 ['campaigns',d=>d.candidate.campaigns.mixed.reverse()],
 ['history',d=>d.candidate.historicalClosures.HIST01=['CASE-B']],
 ['author',d=>d.candidate.productAuthors.push('second-author')],
 ['capability evidence',d=>d.ledger.apiItems[0].evidence=[{path:'different.json',sha256:'b'.repeat(64)}]]
];
for(const [name,change] of snapshotChanges)run('old approvals reject changed '+name,'AMR-04',change,'REVIEW_INPUT_SNAPSHOT_MISMATCH',{fresh:false});
run('critic must bind actual architect report hash','AMR-04',d=>d.candidate.reviews[1].architectReportSha256='b'.repeat(64),'CRITIC_ARCHITECT_BINDING_MISSING');
run('both reviews must include identical snapshot','AMR-04',d=>d.candidate.reviews[1].reviewedInputs={wrong:true},'REVIEW_INPUT_SNAPSHOT_MISMATCH',{fresh:false});
run('nonstring reviewer identity rejects','AMR-05',d=>d.candidate.reviews[0].reviewerId=['product-author'],'INDEPENDENT_REVIEW_MISSING');
run('normalized author cannot review own candidate','AMR-05',d=>d.candidate.reviews[0].reviewerId=' ＰＲＯＤＵＣＴ-ＡＵＴＨＯＲ ','INDEPENDENT_REVIEW_MISSING');
run('normalized reviewer aliases cannot be two identities','AMR-05',d=>d.candidate.reviews[1].reviewerId=' INDEPENDENT-0 ','REVIEW_SEQUENCE_OR_IDENTITY');
run('third blocking critic cannot be masked','AMR-06',d=>d.candidate.reviews.push({...structuredClone(d.candidate.reviews[1]),verdict:'REQUEST CHANGES',blockers:['block']}),'REVIEW_CARDINALITY_INVALID');
run('two copies of same role reject','AMR-06',d=>d.candidate.reviews[1].role='architect','REVIEW_CARDINALITY_INVALID');
run('equal disk and download hashes must match original artifact','AMR-07',d=>{
 const x=d.records.find(r=>r.kind==='download-complete').observations[0].download;x.sha256='b'.repeat(64);x.diskFile={...x.diskFile,sha256:x.sha256};
},'DISK_DOWNLOAD_NOT_PROVEN');
run('artifact run identity mismatch rejects','AMR-07',d=>d.records.find(r=>r.kind==='download-complete').observations[0].download.artifact.runId='different-run','DISK_DOWNLOAD_NOT_PROVEN');
run('artifact payload must carry original SHA','AMR-07',d=>{const a=d.records.find(r=>r.kind==='download-complete').observations[0].download.artifact;a.payloadFile={...a.payloadFile,sha256:'b'.repeat(64)};},'DISK_DOWNLOAD_NOT_PROVEN');
run('stable hash-only ref rejects','AMR-08',d=>d.candidate.environments[1].versionEvidence={sha256:d.candidate.environments[1].versionEvidence.sha256},'VERSION_MATRIX_MISSING');
run('original/additional intersection cannot inflate denominator','AMR-09',d=>d.ledger.additionalCaseResults['CASE-A']={status:'failed',pass:false},'OVERLAPPING_CASE_DENOMINATOR');
for(const [name,change,code] of [
 ['null evidence ref',d=>d.records[0].observations[0].evidence=[null],'OBSERVATION_INCOMPLETE'],
 ['array evidence ref',d=>d.records[0].observations[0].evidence=[[]],'OBSERVATION_INCOMPLETE'],
 ['nonstring ref path',d=>d.records[0].observations[0].evidence=[{path:1,sha256:'a'.repeat(64)}],'OBSERVATION_INCOMPLETE'],
 ['null observation',d=>d.records[0].observations[0]=null,'OBSERVATION_MATRIX_MISSING'],
 ['null environment',d=>d.candidate.environments[0]=null,'INVALID_ENVIRONMENTS'],
 ['null review',d=>d.candidate.reviews[0]=null,'REVIEW_CARDINALITY_INVALID'],
 ['null reviews container',d=>d.candidate.reviews=null,'REVIEW_CARDINALITY_INVALID'],
 ['null diskFile',d=>d.records.find(r=>r.kind==='download-complete').observations[0].download.diskFile=null,'DISK_DOWNLOAD_NOT_PROVEN']
])run(name+' returns structured rejection','AMR-10',change,code);

const isObject=v=>v!==null&&typeof v==='object'&&!Array.isArray(v),isHash=v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v),own=(v,k)=>v!=null&&Object.hasOwn(v,k);
const AsyncFunction=Object.getPrototypeOf(async function(){}).constructor;
const strictSource=checker.slice(checker.indexOf('  const checked = new Map();'),checker.indexOf('  for (const ref of candidate.resultReports'));
const traverseSource=checker.slice(checker.indexOf('  async function references(value)'),checker.indexOf('  await references(candidate);'));
const ioSource=checker.slice(checker.indexOf('  for (const record of records) for (const observation'),checker.indexOf('  for (const record of records) for (const [path, sha256]'));
const reviewSource=checker.slice(checker.indexOf('  for (const review of Array.isArray(candidate.reviews)'),checker.indexOf('  const result = validateAcceptance'));
async function harness({files=new Map(),filesystem=false}={}) {
 const issues=[],add=(code,subject)=>issues.push({code,subject});
 const io=filesystem?readFile:async path=>{if(!files.has(path))throw new Error('ENOENT');return files.get(path);};
 const f=new AsyncFunction('readFile','resolve','projectRoot','sha','own','isObject','isHash','add',
 strictSource+traverseSource+'\nreturn {reference,references};');
 return {...await f(io,resolve,root,hash,own,isObject,isHash,add),issues,add};
}
function ref(files,path,value){const bytes=Buffer.isBuffer(value)?value:Buffer.from(JSON.stringify(value));files.set(resolve(root,path),bytes);return {path,sha256:hash(bytes)};}
async function ioTest(name,finding,change,expected) {
 const files=new Map(), payload=Buffer.from('artifact-original-payload'), payloadRef=ref(files,'payload',payload),diskRef=ref(files,'disk',payload);
 const artifact={artifactId:'artifact-1',runId:'run-1',bytes:payload.length,sha256:hash(payload)};
 const artifactRef=ref(files,'descriptor',{artifact});
 const occurrence={resultId:'campaign-1',roundId:'round-1',sessionId:'session-1',startMs:1,endMs:2};
 const occurrenceRef=ref(files,'round-log',{rows:[occurrence]});
 const download={state:'complete',...artifact,evidence:[diskRef],diskFile:diskRef,artifact:{...artifact,record:artifactRef,payloadFile:payloadRef}};
 const observation={environmentId:'minimum',evidence:[occurrenceRef],occurrence:{...occurrence,evidence:occurrenceRef,pointer:'/rows/0'},download};
 const recordData={id:'campaign-1',observations:[observation]};
 change({files,download,observation,recordData,artifact,ref});
 const h=await harness({files});
 try {await new AsyncFunction('records','reference','references','isObject','sha','add',ioSource)([recordData],h.reference,h.references,isObject,hash,h.add);
 const codes=[...new Set(h.issues.map(x=>x.code))];record(name,finding,expected||'no issues',{passed:expected?codes.includes(expected):codes.length===0,codes,method:'exact current IO branch; in-memory readFile, real hashes'});}
 catch(e){record(name,finding,expected,{passed:false,error:String(e)});}
}
await ioTest('valid occurrence/artifact IO branch','BASELINE',()=>{},null);
await ioTest('raw pointer identity mismatch','AMR-02',({observation})=>observation.occurrence.roundId='invented','OCCURRENCE_RAW_BINDING_MISMATCH');
await ioTest('raw pointer timestamp mismatch','AMR-02',({observation})=>observation.occurrence.endMs=3,'OCCURRENCE_RAW_BINDING_MISMATCH');
await ioTest('raw pointer missing path','AMR-02',({observation})=>observation.occurrence.pointer='/rows/99','OCCURRENCE_RAW_BINDING_MISMATCH');
await ioTest('self-consistent hashes do not override original artifact descriptor','AMR-07',({files,download,ref})=>{
 const other=Buffer.from('other-content');download.sha256=hash(other);download.bytes=other.length;
 download.diskFile=ref(files,'disk-other',other);download.artifact.sha256=download.sha256;download.artifact.bytes=download.bytes;download.artifact.payloadFile=ref(files,'payload-other',other);
},'ARTIFACT_DISK_BINDING_MISMATCH');
await ioTest('native artifact runId actually parsed','AMR-07',({download})=>{download.runId='different-run';download.artifact.runId='different-run';},'ARTIFACT_DISK_BINDING_MISMATCH');
await ioTest('bytes actually read, not only self-filled','AMR-07',({download})=>{download.bytes++;download.artifact.bytes++;},'ARTIFACT_DISK_BINDING_MISMATCH');
for(const [name,mutate,expected] of [
 ['filesystem correct catalog ref',r=>r,null],
 ['filesystem forged hash',r=>({...r,sha256:'b'.repeat(64)}),'EVIDENCE_HASH_MISMATCH'],
 ['filesystem missing path',r=>({...r,path:'docs/framework/evidence/continuation-20261003-current/__followup_nonexistent__'}),'EVIDENCE_FILE_MISSING'],
 ['filesystem hash-only ref',r=>({sha256:r.sha256}),'INVALID_REFERENCE'],
 ['filesystem null ref',()=>null,'INVALID_REFERENCE']
]) {
 const h=await harness({filesystem:true}), bytes=await readFile(resolve(root,SUPPLEMENTAL_CATALOG));
 await h.reference(mutate({path:SUPPLEMENTAL_CATALOG,sha256:hash(bytes)}));
 const codes=[...new Set(h.issues.map(x=>x.code))];
 record(name,'AMR-08/AMR-10',expected||'no issues',{passed:expected?codes.includes(expected):codes.length===0,codes,method:'exact reference function; actual filesystem read'});
}
async function reviewTest(name,change,expected) {
 const files=new Map(), review=structuredClone(fixture().candidate.reviews[0]), report=structuredClone(review);
 delete report.report;
 const realFixtureRef=ref(files,'validator-fixture-only.json',{synthetic:true});
 function fixRefs(v){if(!v||typeof v!=='object')return;if(v.path==='validator-fixture-only.json')v.sha256=realFixtureRef.sha256;for(const x of Object.values(v))if(x&&typeof x==='object')fixRefs(x);}
 fixRefs(review);fixRefs(report);
 const candidate={reviews:[review]};change({files,review,report,candidate});
 if(candidate.reviews[0])review.report=ref(files,'architect-review',report);
 const h=await harness({files});
 try{await new AsyncFunction('candidate','reference','references','add',reviewSource)(candidate,h.reference,h.references,h.add);
 const codes=[...new Set(h.issues.map(x=>x.code))];record(name,'AMR-11/AMR-10',expected||'no issues',{passed:expected?codes.includes(expected):codes.length===0,codes,method:'exact parsed-review IO branch; in-memory readFile, real hashes'});}
 catch(e){record(name,'AMR-11/AMR-10',expected,{passed:false,error:String(e)});}
}
await reviewTest('valid parsed architect report',()=>{},null);
await reviewTest('parsed report nested missing evidence read',({report})=>report.extra={path:'nonexistent-raw',sha256:'a'.repeat(64)},'EVIDENCE_FILE_MISSING');
await reviewTest('parsed report nested forged evidence hash read',({files,report})=>{
 ref(files,'actual-raw',{event:'native-placeholder'});report.extra={path:'actual-raw',sha256:'b'.repeat(64)};
},'EVIDENCE_HASH_MISMATCH');
await reviewTest('CLI review loop null row fails closed without TypeError',({candidate})=>candidate.reviews=[null],'INVALID_REFERENCE');
await reviewTest('parsed report reviewedInputs must match manifest',({report})=>report.reviewedInputs={different:true},'REVIEW_REPORT_MISMATCH');

const catalogBytes=await readFile(resolve(root,SUPPLEMENTAL_CATALOG)),catalog=JSON.parse(catalogBytes);
const ledgerBytes=await readFile(resolve(root,'docs/framework/source-compatibility-ledger.json')),ledger=JSON.parse(ledgerBytes);
const expectedIds=Array.from({length:19},(_,i)=>'F2-K2-SDK-'+String(i+1).padStart(3,'0'));
const catalogIds=catalog.cases.map(r=>r.id),ledgerIds=Object.keys(ledger.additionalCaseResults);
const sourceFiles=[];
for(const path of [...new Set(catalog.cases.map(r=>r.source.path))])sourceFiles.push({path,sha256:hash(await readFile(path))});
const literalHash=checker.match(/const supplementalHash = '([a-f0-9]+)'/)[1];
record('catalog inherits exact existing SDK001-019; fixed bytes and original source','AMR-03',
 '19 matching IDs, required F3, fixed SHA, actual source SHA',
 {passed:JSON.stringify(catalogIds)===JSON.stringify(expectedIds)&&JSON.stringify([...ledgerIds].sort())===JSON.stringify([...expectedIds].sort())&&
 catalog.cases.every(r=>r.required===true&&r.phase==='F3'&&sourceFiles.some(s=>s.path===r.source.path&&s.sha256===r.source.sha256))&&hash(catalogBytes)===literalHash,
 catalogIds,ledgerIds,catalogSha256:hash(catalogBytes),sourceFiles,approvalBoundary:catalog.approvalBoundary});
const inputs=[
 checkerPath,testPath,resolve(root,SUPPLEMENTAL_CATALOG),resolve(root,'docs/framework/product-acceptance-workflow-20261003.md'),
 resolve(root,'docs/framework/evidence/continuation-20261003-current/acceptance-mechanism-review.json'),
 resolve(root,'docs/framework/evidence/continuation-20261003-current/acceptance-mechanism-review.md')
];
const snapshot=[];for(const path of inputs)snapshot.push({path,sha256:hash(await readFile(path))});
console.log(JSON.stringify({schemaVersion:1,kind:'independent-mechanism-followup-probes',generatedAt:new Date().toISOString(),
 total:output.length,passed:output.filter(x=>x.passed).length,failed:output.filter(x=>!x.passed).length,
 snapshot,probes:output},null,2));
